function d_ideate(P,R){var n=P.n||6,out=[];for(var i=0;i<n;i++){var nov=+(0.3+0.7*R()).toFixed(3),fea=+(0.3+0.7*R()).toFixed(3);out.push({id:'IDEA-'+(i+1),novelty:nov,feasibility:fea,score:+(0.6*nov+0.4*fea).toFixed(3)});}out.sort(function(a,b){return b.score-a.score;});return{objective:P.objective||'invention',candidates:out.slice(0,3),evaluated:n};}

